import React, { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import {
  Alert,
  AutoComplete,
  Badge,
  Button,
  Collapse,
  Drawer,
  Empty,
  Flex,
  Form,
  Input,
  Modal,
  Select,
  Space,
  Switch,
  Table,
  Tabs,
  Descriptions,
  Popconfirm,
  Tag,
  Typography,
  Tooltip
} from 'antd';

const FAMILY_PATH = '/api/console/settings/model-providers/plugins/families';
const CATALOG_PATH = '/api/console/settings/model-providers/catalog';
const INSTANCES_PATH = '/api/console/settings/model-providers/instances';
const OPTIONS_PATH = '/api/console/settings/model-providers/options';
const PREVIEW_PATH = '/api/console/settings/model-providers/preview-models';
const PROVIDER_CHANGED_EVENT = 'frontstage:model-provider-catalog-changed';

const cardStyle = {
  background: '#fff',
  border: '1px solid rgba(5, 5, 5, 0.08)',
  borderRadius: 8,
  marginBottom: 16,
  overflow: 'hidden'
};

const cardTitleStyle = {
  minHeight: 52,
  padding: '12px 16px',
  display: 'flex',
  alignItems: 'center',
  justifyContent: 'space-between',
  gap: 12,
  borderBottom: '1px solid rgba(5, 5, 5, 0.08)',
  background: 'rgba(0, 0, 0, 0.015)'
};

function asRecord(value) {
  return value && typeof value === 'object' ? value : null;
}

function readDotted(bundle, key) {
  if (!key) return null;
  let current = bundle;
  for (const part of key.split('.')) {
    current = asRecord(current)?.[part];
    if (current === undefined) return null;
  }
  return typeof current === 'string' ? current : null;
}

function localized(response, entry, keyName) {
  const key = entry?.[keyName];
  const namespace = entry?.namespace;
  if (!key || !namespace) return null;
  const localeCatalog = asRecord(asRecord(response?.i18n_catalog)?.[namespace]);
  if (!localeCatalog) return null;
  const localeMeta = asRecord(response?.locale_meta) || {};
  const preferred = [localeMeta.resolved_locale, localeMeta.fallback_locale, 'zh_Hans', 'en_US'];
  for (const locale of preferred) {
    const value = readDotted(asRecord(localeCatalog?.[locale]), key);
    if (value) return value;
  }
  for (const bundle of Object.values(localeCatalog)) {
    const value = readDotted(asRecord(bundle), key);
    if (value) return value;
  }
  return null;
}

function localizedSchemaText(response, entry, key) {
  if (!key || !entry?.namespace) return null;
  const localeCatalog = asRecord(asRecord(response?.i18n_catalog)?.[entry.namespace]);
  if (!localeCatalog) return null;
  const localeMeta = asRecord(response?.locale_meta) || {};
  const preferred = [localeMeta.resolved_locale, localeMeta.fallback_locale, 'zh_Hans', 'en_US'];
  for (const locale of preferred) {
    const value = readDotted(asRecord(localeCatalog?.[locale]), key);
    if (value) return value;
  }
  return null;
}

function fieldFallbackLabel(key) {
  const labels = {
    base_url: 'API Endpoint',
    api_key: 'API Key',
    proxy_url: '代理地址',
    authorization_header: 'Authorization Header',
    organization: 'Organization',
    project: 'Project',
    api_version: 'API Version',
    default_headers: '默认请求头',
    transport_mode: '传输模式',
    anthropic_version: 'Anthropic Version'
  };
  return labels[key] || key;
}

function statusLabel(status) {
  if (status === 'ready') return ['可用', 'green'];
  if (status === 'invalid') return ['异常', 'red'];
  if (status === 'draft') return ['草稿', 'default'];
  if (status === 'disabled') return ['已禁用', 'default'];
  return [status || '未知', 'default'];
}

function optionControlValue(value) {
  if (typeof value === 'string' || typeof value === 'number') return value;
  if (typeof value === 'boolean') return value ? 'true' : 'false';
  return JSON.stringify(value ?? '');
}

function buildCreateInitialValues(entry) {
  const config = {};
  for (const field of entry?.form_schema || []) {
    if (field.key === 'validate_model') continue;
    if (field.default_value !== undefined && field.default_value !== null) {
      config[field.key] = field.field_type === 'enum' || field.control === 'select'
        ? optionControlValue(field.default_value)
        : field.default_value;
    } else if (field.key === 'base_url' && entry.default_base_url) {
      config[field.key] = entry.default_base_url;
    } else if (field.field_type === 'boolean') {
      config[field.key] = false;
    }
  }
  return {
    display_name: entry?.display_name || '',
    included_in_main: false,
    config
  };
}

function resolveConfig(entry, values) {
  const config = {};
  const draft = values || {};
  for (const field of entry?.form_schema || []) {
    if (field.key === 'validate_model') continue;
    const value = draft[field.key];
    if (value === undefined || value === '') continue;
    if (field.field_type === 'enum' || field.control === 'select') {
      const option = (field.options || []).find((item) => optionControlValue(item.value) === value);
      config[field.key] = option ? option.value : value;
    } else {
      config[field.key] = value;
    }
  }
  return config;
}

function parseContextWindow(value) {
  const raw = String(value || '').trim();
  if (!raw) return null;
  const match = raw.match(/^(\d+(?:\.\d+)?)\s*([kKmM])?$/);
  if (!match) throw new Error('请输入数字，或使用 128K、1M 格式');
  const multiplier = match[2]?.toLowerCase() === 'm' ? 1000000 : match[2] ? 1000 : 1;
  const parsed = Number(match[1]) * multiplier;
  if (!Number.isSafeInteger(parsed) || parsed <= 0) throw new Error('上下文必须是正整数');
  return parsed;
}

function modelRowFromDescriptor(model, key) {
  return {
    key,
    model_id: model?.model_id || '',
    context_window_input: model?.context_window ? String(model.context_window) : '',
    supports_multimodal: Boolean(model?.supports_multimodal),
    enabled: true,
    pricing_provider_code: 'zero',
    pricing_model_id: 'any'
  };
}

export default function ProviderInstancesBlock({ ctx }) {
  const [familiesResponse, setFamiliesResponse] = useState({ entries: [] });
  const [catalogResponse, setCatalogResponse] = useState({ entries: [] });
  const [optionsResponse, setOptionsResponse] = useState({ pricing_targets: [] });
  const [instances, setInstances] = useState([]);
  const [selected, setSelected] = useState(null);
  const [editingInstance, setEditingInstance] = useState(null);
  const [createIncludedInMain, setCreateIncludedInMain] = useState(false);
  const [canManage, setCanManage] = useState(false);
  const [query, setQuery] = useState('');
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState(null);
  const [notice, setNotice] = useState(null);
  const [drawerEntry, setDrawerEntry] = useState(null);
  const [familyOperation, setFamilyOperation] = useState(null);
  const [familyTask, setFamilyTask] = useState(null);
  const [upgradeConfirmation, setUpgradeConfirmation] = useState(null);
  const familyOperationRef = useRef(false);
  const [drawerNotice, setDrawerNotice] = useState(null);
  const [submitting, setSubmitting] = useState(false);
  const [previewing, setPreviewing] = useState(false);
  const [previewModels, setPreviewModels] = useState([]);
  const [previewToken, setPreviewToken] = useState(null);
  const [configuredModels, setConfiguredModels] = useState([]);
  const [selectedCachedModelId, setSelectedCachedModelId] = useState(null);
  const [modelEditor, setModelEditor] = useState(null);
  const [drawerWidth, setDrawerWidth] = useState(560);
  const [draftInstanceId, setDraftInstanceId] = useState(null);
  const [authBusy, setAuthBusy] = useState(false);
  const [authResult, setAuthResult] = useState(null);
  const [callbackValue, setCallbackValue] = useState('');
  const [createForm] = Form.useForm();
  const [modelForm] = Form.useForm();
  const modelKeyRef = useRef(0);
  const apiRef = useRef(ctx.api);
  const localeRef = useRef(ctx.ui.locale || 'zh_Hans');
  apiRef.current = ctx.api;
  localeRef.current = ctx.ui.locale || 'zh_Hans';

  const refresh = useCallback(async () => {
    setBusy(true);
    setError(null);
    try {
      const [families, catalog, currentInstances, options, me] = await Promise.all([
        apiRef.current.get(FAMILY_PATH, { query: { plugin_type: 'model_provider', locale: localeRef.current } }),
        apiRef.current.get(CATALOG_PATH, { query: { locale: localeRef.current } }),
        apiRef.current.get(INSTANCES_PATH),
        apiRef.current.get(OPTIONS_PATH),
        apiRef.current.get('/api/console/me')
      ]);
      setCanManage(me.effective_display_role === 'root' || me.permissions.some((permission) => ['state_model.manage.all', 'state_model.manage.own'].includes(permission)));
      setFamiliesResponse(families || { entries: [] });
      setCatalogResponse(catalog || { entries: [] });
      setInstances(Array.isArray(currentInstances) ? currentInstances : []);
      setOptionsResponse(options || { pricing_targets: [] });
      return true;
    } catch (reason) {
      setError('模型供应商数据加载失败，请稍后重试。');
      setCanManage(false);
      return false;
    } finally {
      setBusy(false);
    }
  }, []);

  useEffect(() => {
    refresh();
    const listener = () => refresh();
    window.addEventListener(PROVIDER_CHANGED_EVENT, listener);
    return () => window.removeEventListener(PROVIDER_CHANGED_EVENT, listener);
  }, [refresh]);

  useEffect(() => {
    if (!drawerEntry) return;
    createForm.resetFields();
    const initial = buildCreateInitialValues(drawerEntry);
    initial.included_in_main = createIncludedInMain;
    if (editingInstance) {
      initial.display_name = editingInstance.display_name;
      initial.included_in_main = editingInstance.included_in_main;
      for (const field of drawerEntry.form_schema) {
        const value = editingInstance.config_json[field.key];
        if (field.field_type === 'secret') initial.config[field.key] = '';
        else if (value !== undefined) initial.config[field.key] =
          field.field_type === 'enum' || field.control === 'select' ? optionControlValue(value) : value;
      }
    }
    createForm.setFieldsValue(initial);
    setDrawerNotice(null);
    setPreviewModels([]);
    setPreviewToken(null);
    setConfiguredModels((editingInstance?.configured_models || []).map((model) => ({
      ...model, key: 'model-' + modelKeyRef.current++,
      context_window_input: model.context_window_override_tokens == null ? '' : String(model.context_window_override_tokens)
    })));
    setSelectedCachedModelId(null);
    setDraftInstanceId(null);
    setAuthResult(null);
    setCallbackValue('');
  }, [createForm, drawerEntry, editingInstance, createIncludedInMain]);

  useEffect(() => {
    if (!modelEditor) return;
    const defaultPricing =
      (optionsResponse?.pricing_targets || []).find(
        (target) => target.provider_code === 'zero' && target.upstream_model_id === 'any'
      ) || (optionsResponse?.pricing_targets || [])[0];
    modelForm.setFieldsValue({
      model_id: modelEditor.row?.model_id || modelEditor.modelId || '',
      context_window_input: modelEditor.row?.context_window_input || '',
      supports_multimodal: Boolean(modelEditor.row?.supports_multimodal),
      enabled: modelEditor.row?.enabled ?? true,
      pricing_provider_code:
        modelEditor.row?.pricing_provider_code || defaultPricing?.provider_code || 'zero',
      pricing_model_id:
        modelEditor.row?.pricing_model_id || defaultPricing?.upstream_model_id || 'any'
    });
  }, [modelEditor, modelForm, optionsResponse]);

  const rows = useMemo(() => {
    const entries = Array.isArray(familiesResponse?.entries) ? familiesResponse.entries : [];
    const catalogEntries = Array.isArray(catalogResponse?.entries) ? catalogResponse.entries : [];
    return entries.map((entry) => {
      const catalog = catalogEntries.find((item) =>
        item.installation_id === entry.current_installation_id || item.provider_code === entry.provider_code
      );
      return {
        ...entry,
        display_name:
          localized(familiesResponse, entry, 'provider_label_key') ||
          localized(familiesResponse, entry, 'label_key') ||
          catalog?.display_name || entry.provider_code,
        description:
          localized(familiesResponse, entry, 'description_key') ||
          catalog?.description || catalog?.description_key || '暂无说明'
      };
    }).filter((entry) => {
      const needle = query.trim().toLowerCase();
      return !needle || entry.display_name.toLowerCase().includes(needle) || entry.provider_code.toLowerCase().includes(needle);
    });
  }, [familiesResponse, catalogResponse, instances, query]);

  const createCatalogEntries = useMemo(() => {
    const installedProviderCodes = new Set(
      (familiesResponse?.entries || []).map((entry) => entry.provider_code)
    );
    return (catalogResponse?.entries || []).filter((entry) =>
      installedProviderCodes.has(entry.provider_code)
    );
  }, [catalogResponse, familiesResponse]);

  const selectedInstances = useMemo(() => selected
    ? instances.filter((item) => item.provider_code === selected.provider_code)
    : [], [instances, selected]);
  const formSchema = (drawerEntry?.form_schema || []).filter((field) => field.key !== 'validate_model');
  const primaryFields = formSchema.filter((field) => !field.advanced);
  const advancedFields = formSchema.filter((field) => field.advanced);
  const pricingTargets = optionsResponse?.pricing_targets || [];
  const pricingProvider = Form.useWatch('pricing_provider_code', modelForm) || 'zero';
  const pricingProviderOptions = Array.from(new Set(pricingTargets.map((target) => target.provider_code)))
    .map((value) => ({ label: value, value }));
  const pricingModelOptions = pricingTargets
    .filter((target) => target.provider_code === pricingProvider)
    .map((target) => ({ label: target.upstream_model_id, value: target.upstream_model_id }));

  async function openCreate(entry) {
    if (!canManage || busy) return;
    setBusy(true);
    try {
      const main = await apiRef.current.get('/api/console/settings/model-providers/providers/{provider_code}/main-instance', {
        path: { provider_code: entry.provider_code }
      });
      setCreateIncludedInMain(main.auto_include_new_instances);
      setEditingInstance(null);
      setDrawerEntry(entry);
    } catch {
      setNotice({ type: 'error', message: '新增来源配置加载失败，请重试。' });
    } finally { setBusy(false); }
  }

  async function requestUpgrade(entry) {
    if (!canManage || familyOperationRef.current || !entry.has_update) return;
    familyOperationRef.current = true;
    setFamilyOperation({ mode: 'checking', providerCode: entry.provider_code });
    try {
      const catalog = await apiRef.current.get('/api/console/plugins/official-catalog', {
        query: { q: entry.provider_code, limit: 20, locale: localeRef.current }
      });
      const official = catalog.entries.find((item) =>
        item.provider_code === entry.provider_code && item.latest_version === entry.latest_version
      ) || catalog.entries.find((item) => item.provider_code === entry.provider_code);
      if (!official) {
        setNotice({ type: 'error', message: '官方供应商目录不可用，请刷新后重试。' });
        return;
      }
      setUpgradeConfirmation({ entry, official });
    } catch {
      setNotice({ type: 'error', message: '更新信息加载失败，请重试。' });
    } finally {
      familyOperationRef.current = false;
      setFamilyOperation(null);
    }
  }

  async function runFamilyOperation(mode, entry, installationId, compatibilityOverride) {
    if (!canManage || familyOperationRef.current) return;
    familyOperationRef.current = true;
    setFamilyOperation({ mode, providerCode: entry.provider_code });
    setNotice(null);
    try {
      const path = { provider_code: entry.provider_code };
      const familyPath = '/api/console/plugins/families/{provider_code}';
      const task = mode === 'uninstall'
        ? await apiRef.current.delete(familyPath, { path })
        : await apiRef.current.post(familyPath + (mode === 'upgrade' ? '/upgrade-latest' : '/switch-version'), {
            path,
            ...(mode === 'switch'
              ? { body: { installation_id: installationId } }
              : compatibilityOverride ? { body: { compatibility_override: compatibilityOverride } } : {})
          });
      setUpgradeConfirmation(null);
      setFamilyTask(task);
    } catch {
      familyOperationRef.current = false;
      setFamilyOperation(null);
      setNotice({ type: 'error', message: '插件操作失败，请刷新后重试。' });
    }
  }

  useEffect(() => {
    if (!familyTask) return;
    let active = true;
    let timer;
    const terminal = ['success', 'succeeded', 'failed', 'canceled', 'timed_out'];
    async function observe() {
      try {
        let task = familyTask;
        if (!task.finished_at && !terminal.includes(task.status)) {
          task = await apiRef.current.get('/api/console/plugins/tasks/{task_id}', { path: { task_id: task.id } });
        }
        if (!active) return;
        if (!task.finished_at && !terminal.includes(task.status)) {
          timer = window.setTimeout(observe, 1000);
          return;
        }
        const succeeded = task.status === 'success' || task.status === 'succeeded';
        setFamilyTask(null);
        setFamilyOperation(null);
        familyOperationRef.current = false;
        setNotice({ type: succeeded ? 'success' : 'error',
          message: succeeded ? '插件操作已完成。' : '插件操作未完成，请刷新后查看当前状态。' });
        if (succeeded) {
          setSelected(null);
          setDrawerEntry(null);
          setEditingInstance(null);
          window.dispatchEvent(new Event(PROVIDER_CHANGED_EVENT));
        }
      } catch {
        if (!active) return;
        setFamilyTask(null);
        setFamilyOperation(null);
        familyOperationRef.current = false;
        setNotice({ type: 'warning', message: '暂时无法查询插件任务结果，任务可能仍在执行，请刷新后查看状态。' });
      }
    }
    void observe();
    return () => { active = false; window.clearTimeout(timer); };
  }, [familyTask]);

  async function openEdit(instance) {
    if (!canManage) return;
    const entry = catalogResponse.entries.find((item) => item.installation_id === instance.installation_id);
    if (!entry) { setNotice({ type: 'error', message: '该来源的插件配置不可用，请刷新供应商列表。' }); return; }
    setEditingInstance(instance);
    setDrawerEntry(entry);
  }

  useEffect(() => {
    if (!editingInstance || !drawerEntry) return;
    let active = true;
    apiRef.current.get(INSTANCES_PATH + '/{id}/models', { path: { id: editingInstance.id } })
      .then((catalog) => { if (active) setPreviewModels(catalog.models); })
      .catch(() => { if (active) setDrawerNotice({ type: 'warning', message: '缓存模型加载失败，可重试检测；已有模型配置仍可编辑。' }); });
    return () => { active = false; };
  }, [editingInstance, drawerEntry]);

  async function closeCreate() {
    if (submitting || previewing || authBusy) return;
    const disposableDraftId = draftInstanceId;
    setDrawerEntry(null);
    setEditingInstance(null);
    setModelEditor(null);
    setDraftInstanceId(null);
    createForm.resetFields();
    if (disposableDraftId) {
      try {
        await apiRef.current.delete(INSTANCES_PATH + '/{id}', { path: { id: disposableDraftId } });
      } catch (reason) {
        setNotice({ type: 'error', message: '授权草稿回收失败，请刷新后重试。' });
      }
    }
  }

  async function runAuthorization(operation) {
    if (!drawerEntry || !canManage || authBusy) return;
    setAuthBusy(true);
    setDrawerNotice(null);
    try {
      let instanceId = editingInstance?.id || draftInstanceId;
      if (!instanceId) {
        const values = await createForm.validateFields();
        const draft = await apiRef.current.post(INSTANCES_PATH, {
          body: {
            installation_id: drawerEntry.installation_id,
            display_name: values.display_name,
            included_in_main: Boolean(values.included_in_main),
            config: resolveConfig(drawerEntry, values.config),
            configured_models: []
          }
        });
        instanceId = draft.id;
        setDraftInstanceId(instanceId);
      }
      const response = await apiRef.current.post(INSTANCES_PATH + '/{id}/authenticate', {
        path: { id: instanceId },
        body: { operation }
      });
      setAuthResult(response);
      if (response?.status === 'authorized') {
        setDrawerNotice({ type: 'success', message: response.message || '授权已完成。' });
      } else if (response?.status === 'failed') {
        setDrawerNotice({ type: 'error', message: response.message || '授权失败，请重试。' });
      }
    } catch (reason) {
      if (reason?.errorFields) return;
      setDrawerNotice({
        type: 'error',
        message: reason instanceof Error ? reason.message : '授权操作失败，请重试。'
      });
    } finally {
      setAuthBusy(false);
    }
  }

  function renderConfigField(field) {
    const label =
      localizedSchemaText(catalogResponse, drawerEntry, field.label) || fieldFallbackLabel(field.key);
    const description = localizedSchemaText(catalogResponse, drawerEntry, field.description);
    const placeholder =
      localizedSchemaText(catalogResponse, drawerEntry, field.placeholder) || field.placeholder || '请输入';
    const rules = field.required && !(editingInstance && field.field_type === 'secret') ? [{ required: true, message: '请输入' + label }] : [];
    let control;
    if (field.field_type === 'boolean') {
      control = <Switch />;
    } else if (field.field_type === 'enum' || field.control === 'select') {
      control = (
        <Select
          placeholder={placeholder}
          options={(field.options || []).map((option) => ({
            label: localizedSchemaText(catalogResponse, drawerEntry, option.label) || String(option.label || option.value),
            value: optionControlValue(option.value),
            disabled: Boolean(option.disabled)
          }))}
        />
      );
    } else if (field.key.includes('headers') || field.key.includes('json') || field.key.includes('schema')) {
      control = <Input.TextArea rows={3} placeholder={placeholder} />;
    } else if (field.field_type === 'secret') {
      control = <Input.Password placeholder={placeholder} autoComplete="new-password" />;
    } else {
      control = <Input placeholder={placeholder} />;
    }
    return (
      <Form.Item
        key={field.key}
        name={['config', field.key]}
        label={label}
        extra={editingInstance && field.field_type === 'secret' ? '留空保留已保存的密钥；填写新值后保存以替换。' : description}
        valuePropName={field.field_type === 'boolean' ? 'checked' : 'value'}
        rules={rules}
      >
        {control}
      </Form.Item>
    );
  }

  async function detectModels() {
    if (!drawerEntry || !canManage || previewing) return;
    setPreviewing(true);
    setDrawerNotice(null);
    try {
      const values = await createForm.validateFields();
      const response = await apiRef.current.post(PREVIEW_PATH, {
        body: {
          ...(editingInstance || draftInstanceId ? { instance_id: editingInstance?.id || draftInstanceId } : { installation_id: drawerEntry.installation_id }),
          config: resolveConfig(drawerEntry, values.config)
        }
      });
      const models = Array.isArray(response?.models) ? response.models : [];
      setPreviewModels(models);
      setPreviewToken(response?.preview_token || null);
      setDrawerNotice({ type: 'success', message: `检测完成，发现 ${models.length} 个模型。` });
    } catch (reason) {
      if (reason?.errorFields) return;
      setDrawerNotice({
        type: 'error',
        message: reason instanceof Error ? reason.message : '连接检测失败，请检查配置。'
      });
    } finally {
      setPreviewing(false);
    }
  }

  function importAllModels() {
    setConfiguredModels((current) => {
      const existing = new Set(current.map((row) => row.model_id));
      const next = [...current];
      for (const model of previewModels) {
        if (!model?.model_id || existing.has(model.model_id)) continue;
        next.push(modelRowFromDescriptor(model, `model-${modelKeyRef.current++}`));
        existing.add(model.model_id);
      }
      return next;
    });
  }

  async function saveModelEditor() {
    const values = await modelForm.validateFields();
    const modelId = values.model_id.trim();
    const duplicate = configuredModels.some(
      (row, index) => index !== modelEditor?.index && row.model_id === modelId
    );
    if (duplicate) {
      modelForm.setFields([{ name: 'model_id', errors: ['模型 ID 已存在'] }]);
      return;
    }
    const row = {
      key: modelEditor?.row?.key || `model-${modelKeyRef.current++}`,
      model_id: modelId,
      context_window_input: String(values.context_window_input || '').trim(),
      supports_multimodal: Boolean(values.supports_multimodal),
      enabled: Boolean(values.enabled),
      pricing_provider_code: values.pricing_provider_code || 'zero',
      pricing_model_id: values.pricing_model_id || 'any'
    };
    setConfiguredModels((current) =>
      modelEditor?.index === null || modelEditor?.index === undefined
        ? [...current, row]
        : current.map((item, index) => index === modelEditor.index ? row : item)
    );
    setModelEditor(null);
  }

  async function submitCreate() {
    if (!drawerEntry || !canManage || submitting || previewing || authBusy) return;
    setSubmitting(true);
    setDrawerNotice(null);
    try {
      const values = await createForm.validateFields();
      const body = {
        display_name: values.display_name,
        included_in_main: Boolean(values.included_in_main),
        config: resolveConfig(drawerEntry, values.config),
        configured_models: configuredModels.map((row) => ({
          model_id: row.model_id,
          enabled: row.enabled,
          context_window_override_tokens: parseContextWindow(row.context_window_input),
          supports_multimodal: row.supports_multimodal,
          pricing_provider_code: row.pricing_provider_code,
          pricing_model_id: row.pricing_model_id
        })),
        preview_token: previewToken || undefined
      };
      if (editingInstance || draftInstanceId) {
        await apiRef.current.patch(INSTANCES_PATH + '/{id}', { path: { id: editingInstance?.id || draftInstanceId }, body });
      } else {
        await apiRef.current.post(INSTANCES_PATH, {
          body: { ...body, installation_id: drawerEntry.installation_id }
        });
      }
      setDraftInstanceId(null);
      setDrawerEntry(null);
      createForm.resetFields();
      setNotice({ type: 'success', message: editingInstance ? '模型来源已更新。' : '模型来源已创建。' });
      setEditingInstance(null);
      await refresh();
    } catch (reason) {
      if (reason?.errorFields) return;
      setDrawerNotice({
        type: 'error',
        message: reason instanceof Error ? reason.message : '模型来源创建失败，请重试。'
      });
    } finally {
      setSubmitting(false);
    }
  }

  const modelColumns = [
    { title: '模型 ID', dataIndex: 'model_id', ellipsis: true },
    { title: '上下文', dataIndex: 'context_window_input', width: 90, render: (value) => value || '—' },
    {
      title: '模型计费规则',
      key: 'pricing',
      width: 150,
      render: (_, row) => `${row.pricing_provider_code} / ${row.pricing_model_id}`
    },
    {
      title: '多模态',
      dataIndex: 'supports_multimodal',
      width: 76,
      align: 'center',
      render: (value, row) => (
        <Switch
          size="small"
          checked={value}
          onChange={(checked) => setConfiguredModels((current) =>
            current.map((item) => item.key === row.key ? { ...item, supports_multimodal: checked } : item)
          )}
        />
      )
    },
    {
      title: '启用',
      dataIndex: 'enabled',
      width: 68,
      align: 'center',
      render: (value, row) => (
        <Switch
          size="small"
          checked={value}
          onChange={(checked) => setConfiguredModels((current) =>
            current.map((item) => item.key === row.key ? { ...item, enabled: checked } : item)
          )}
        />
      )
    },
    {
      title: '操作',
      key: 'actions',
      width: 104,
      render: (_, row, index) => (
        <Space size={2}>
          <Button type="link" size="small" onClick={() => setModelEditor({ index, row })}>编辑</Button>
          <Button danger type="link" size="small" onClick={() =>
            setConfiguredModels((current) => current.filter((item) => item.key !== row.key))
          }>删除</Button>
        </Space>
      )
    }
  ];

  return (
    <div style={{ minHeight: 720, padding: '20px 18px 24px', background: 'rgba(255,255,255,0.84)', borderRadius: 16 }}>
      <Space style={{ width: '100%', justifyContent: 'flex-end', marginBottom: 16 }}>
        <Input.Search
          allowClear
          placeholder="搜索供应商"
          value={query}
          onChange={(event) => setQuery(event.target.value)}
          style={{ width: 210 }}
        />
        <Button loading={busy} onClick={refresh}>刷新</Button>
      </Space>

      {error ? <Alert showIcon type="error" message={error} style={{ marginBottom: 14 }} /> : null}
      {notice ? (
        <Alert
          showIcon
          closable
          type={notice.type}
          message={notice.message}
          onClose={() => setNotice(null)}
          style={{ marginBottom: 14 }}
        />
      ) : null}

      <Table
        size="small"
        rowKey="provider_code"
        loading={busy}
        dataSource={rows}
        pagination={false}
        scroll={{ x: 1080 }}
        locale={{ emptyText: <Empty description="暂无已安装的模型供应商" /> }}
        columns={[
          ...(canManage ? [{
            title: '操作', key: 'actions', width: 280,
            render: (_, entry) => {
              const pending = familyOperation?.providerCode === entry.provider_code;
              const catalog = createCatalogEntries.find((item) => item.installation_id === entry.current_installation_id);
              return (
                <Space size={4} wrap style={{ width: '100%', justifyContent: 'flex-start' }}>
                  <Button type="link" style={{ paddingInline: 0 }} disabled={Boolean(familyOperation)} onClick={() => setSelected(entry)}>实例管理</Button>
                  <Button type="link" style={{ paddingInline: 0 }}
                    disabled={busy || Boolean(familyOperation) || entry.current_local_artifact?.artifact_status !== 'ready' || !catalog}
                    onClick={() => catalog && void openCreate(catalog)}>新增</Button>
                  <Tooltip title={entry.has_update ? undefined : entry.latest_version === null ? '更新检查失败' : '当前已是最新版'}>
                    <span><Badge dot={entry.has_update && !pending} color="gold">
                      <Button type="link" style={{ paddingInline: 0 }} loading={pending && ['checking', 'upgrade'].includes(familyOperation.mode)}
                        disabled={!entry.has_update || Boolean(familyOperation)}
                        onClick={() => void requestUpgrade(entry)}>更新</Button>
                    </Badge></span>
                  </Tooltip>
                  <Popconfirm title="卸载插件" description={`确认卸载 ${entry.display_name}？请确认相关模型来源已不再使用。`}
                    okText="卸载" cancelText="取消" okButtonProps={{ danger: true }}
                    onConfirm={() => runFamilyOperation('uninstall', entry)} disabled={Boolean(familyOperation)}>
                    <Button danger type="link" style={{ paddingInline: 0 }} loading={pending && familyOperation.mode === 'uninstall'}
                      disabled={Boolean(familyOperation)}>卸载</Button>
                  </Popconfirm>
                </Space>
              );
            }
          }] : []),
          {
            title: '名称', dataIndex: 'display_name', width: 170,
            render: (value) => <Typography.Text strong>{value}</Typography.Text>
          },
          {
            title: '状态', key: 'status', width: 180,
            render: (_, entry) => (
              <Space wrap size={[6, 6]}>
                <Tag color={entry.current_local_artifact?.artifact_status === 'ready' ? 'green' : 'default'}>
                  {entry.current_local_artifact?.artifact_status === 'ready' ? '可用' : '不可用'}
                </Tag>
                <Tag>{entry.model_discovery_mode || 'unknown'}</Tag>
              </Space>
            )
          },
          {
            title: '版本', dataIndex: 'current_version', width: 220,
            render: (value, entry) => (
              <Space direction="vertical" size={4}>
                {canManage ? <Select size="small" style={{ minWidth: 112 }}
                  aria-label={`切换 ${entry.display_name} 版本`}
                  value={entry.current_installation_id} disabled={Boolean(familyOperation)}
                  loading={familyOperation?.mode === 'switch' && familyOperation.providerCode === entry.provider_code}
                  options={Array.from(entry.installed_versions).sort((left, right) =>
                    right.plugin_version.localeCompare(left.plugin_version, undefined, { numeric: true, sensitivity: 'base' })
                  ).map((version) => ({ value: version.installation_id, label: version.plugin_version }))}
                  onChange={(installationId) => {
                    if (installationId !== entry.current_installation_id) void runFamilyOperation('switch', entry, installationId);
                  }}
                /> : <Typography.Text strong>{value}</Typography.Text>}
                {entry.current_local_artifact?.local_version && entry.current_local_artifact.local_version !== value
                  ? <Typography.Text type="secondary">当前节点版本：{entry.current_local_artifact.local_version}</Typography.Text> : null}
                {entry.current_local_artifact?.last_error
                  ? <Typography.Text type="danger">当前节点错误：{entry.current_local_artifact.last_error}</Typography.Text> : null}
              </Space>
            )
          },
          {
            title: '说明', dataIndex: 'description',
            render: (value) => <Typography.Text type={value === '暂无说明' ? 'secondary' : undefined}>{value}</Typography.Text>
          }
        ]}
      />

      {upgradeConfirmation ? (
        <Modal open title="更新插件" width={640} centered
          okText={upgradeConfirmation.official.compatibility_status === 'below_minimum_host_version' ? '仍然更新' : '更新至最新版本'}
          cancelText="取消" confirmLoading={familyOperation?.mode === 'upgrade'}
          closable={!familyOperation} maskClosable={!familyOperation}
          cancelButtonProps={{ disabled: Boolean(familyOperation) }}
          onCancel={() => !familyOperation && setUpgradeConfirmation(null)}
          onOk={() => {
            const { entry, official } = upgradeConfirmation;
            const override = official.compatibility_status === 'below_minimum_host_version' ? {
              reason: 'below_minimum_host_version',
              acknowledged_current_host_version: official.current_host_version,
              acknowledged_minimum_host_version: official.minimum_host_version
            } : undefined;
            void runFamilyOperation('upgrade', entry, null, override);
          }}>
          <Typography.Title level={5}>{upgradeConfirmation.entry.display_name}</Typography.Title>
          <Typography.Paragraph>将更新至官方版本 {upgradeConfirmation.official.latest_version}，完成后该供应商的模型来源将迁移至新版本。</Typography.Paragraph>
          {upgradeConfirmation.official.compatibility_status === 'below_minimum_host_version' ? (
            <Alert showIcon type="warning" message="当前主机版本低于插件要求"
              description={`当前版本：${upgradeConfirmation.official.current_host_version}；最低版本：${upgradeConfirmation.official.minimum_host_version}。建议先升级 1flowbase，再更新插件。`} />
          ) : null}
        </Modal>
      ) : null}

      {drawerEntry ? (
        <Drawer
          open
          destroyOnHidden
          title={editingInstance ? "编辑来源配置" : "API 密钥授权配置"}
          placement="right"
          size={drawerWidth}
          defaultSize={560}
          minSize={480}
          maxSize={1200}
          resizable={{ onResize: (nextWidth) => setDrawerWidth(nextWidth) }}
          zIndex={1100}
          closable={!submitting && !previewing && !authBusy}
          maskClosable={!submitting && !previewing && !authBusy}
          onClose={() => void closeCreate()}
          styles={{
            body: { padding: 16, background: '#f7f8fa' },
            wrapper: { minWidth: 'min(480px, 100vw)', maxWidth: '100vw' }
          }}
          footer={
            <Space style={{ width: '100%', justifyContent: 'flex-end' }}>
              <Button type="primary" loading={submitting} disabled={!canManage || previewing || authBusy} onClick={() => void submitCreate()}>保存</Button>
              <Button disabled={submitting || previewing || authBusy} onClick={() => void closeCreate()}>取消</Button>
            </Space>
          }
        >
          <Form form={createForm} layout="vertical" disabled={!canManage || submitting} onValuesChange={(changed) => { if (changed.config) setPreviewToken(null); }}>
            {drawerNotice ? (
              <Alert showIcon closable type={drawerNotice.type} message={drawerNotice.message}
                onClose={() => setDrawerNotice(null)} style={{ marginBottom: 16 }} />
            ) : null}

            <div style={cardStyle}>
              <div style={cardTitleStyle}>
                <Space wrap>
                  <Typography.Text strong>{drawerEntry.display_name}</Typography.Text>
                  <Tag color="blue">{drawerEntry.provider_code}</Tag>
                  <Tag color="cyan">{drawerEntry.protocol}</Tag>
                  <Tag color="purple">发现模式 {drawerEntry.model_discovery_mode}</Tag>
                </Space>
              </div>
              <div style={{ padding: 16 }}>
                <Flex gap={20} align="start">
                  <Form.Item
                    name="display_name"
                    label="名称"
                    style={{ flex: 1, marginBottom: 0 }}
                    rules={[{ required: true, whitespace: true, message: '请输入名称' }]}
                  >
                    <Input placeholder="例如：OpenAI Production" />
                  </Form.Item>
                  <Form.Item name="included_in_main" label="纳入主实例" valuePropName="checked" style={{ marginBottom: 0 }}>
                    <Switch />
                  </Form.Item>
                </Flex>
              </div>
            </div>

            {drawerEntry.auth?.actions?.length ? (
              <div style={cardStyle}>
                <div style={cardTitleStyle}><Typography.Text strong>授权方式</Typography.Text></div>
                <div style={{ padding: 16 }}>
                  <Alert type="info" showIcon message={editingInstance ? "授权操作应用于当前来源实例。" : "该插件需要完成外部授权；关闭抽屉时会自动回收未保存草稿。"} />
                  <Space wrap style={{ marginTop: 12 }}>
                    {drawerEntry.auth.actions.map((action) => (
                      <Button
                        key={action.code}
                        loading={authBusy}
                        onClick={() => void runAuthorization({ type: 'begin', action: action.code })}
                      >
                        {action.label || action.code}
                      </Button>
                    ))}
                  </Space>
                  {authResult ? (
                    <div style={{ marginTop: 12 }}>
                      <Space wrap>
                        <Tag color={authResult.status === 'authorized' ? 'green' : authResult.status === 'failed' ? 'red' : 'blue'}>
                          {authResult.status}
                        </Tag>
                        {authResult.message ? <Typography.Text>{authResult.message}</Typography.Text> : null}
                      </Space>
                      {authResult.user_action?.open_url ? (
                        <div style={{ marginTop: 12 }}>
                          <Button href={authResult.user_action.open_url} target="_blank">打开授权页面</Button>
                        </div>
                      ) : null}
                      {authResult.user_action?.user_code ? (
                        <Typography.Paragraph copyable style={{ marginTop: 12, marginBottom: 0 }}>
                          授权码：{authResult.user_action.user_code}
                        </Typography.Paragraph>
                      ) : null}
                      {authResult.user_action?.kind === 'paste_callback_url' ? (
                        <Space.Compact style={{ width: '100%', marginTop: 12 }}>
                          <Input value={callbackValue} placeholder={authResult.user_action.prompt || '粘贴回调地址'} onChange={(event) => setCallbackValue(event.target.value)} />
                          <Button type="primary" loading={authBusy} onClick={() => void runAuthorization({ type: 'submit', value: callbackValue })}>提交</Button>
                        </Space.Compact>
                      ) : null}
                      {authResult.status === 'pending' ? (
                        <Button style={{ marginTop: 12 }} loading={authBusy} onClick={() => void runAuthorization({ type: 'poll' })}>
                          刷新授权状态
                        </Button>
                      ) : null}
                    </div>
                  ) : null}
                </div>
              </div>
            ) : null}

            <div style={cardStyle}>
              <div style={cardTitleStyle}>
                <Typography.Text strong>✓&nbsp; 连接配置</Typography.Text>
                <Button size="small" loading={previewing} onClick={() => void detectModels()}>检测</Button>
              </div>
              <div style={{ padding: 16 }}>
                {primaryFields.map(renderConfigField)}
                {advancedFields.length ? (
                  <Collapse
                    ghost={false}
                    items={[{
                      key: 'advanced',
                      label: '高级配置（可选）',
                      children: advancedFields.map(renderConfigField)
                    }]}
                  />
                ) : null}
              </div>
            </div>

            <div style={cardStyle}>
              <div style={cardTitleStyle}><Typography.Text strong>＋&nbsp; 模型配置</Typography.Text></div>
              <div style={{ padding: 16 }}>
                <Flex align="center" gap={12} style={{ marginBottom: 16 }}>
                  <Select
                    showSearch
                    allowClear
                    style={{ flex: 1 }}
                    value={selectedCachedModelId}
                    placeholder={previewModels.length ? '选择检测到的模型' : '请先检测模型'}
                    disabled={!previewModels.length}
                    options={previewModels.map((model) => ({ label: model.model_id, value: model.model_id }))}
                    onChange={setSelectedCachedModelId}
                  />
                  <Button type="dashed" onClick={() => setModelEditor({ index: null, row: null, modelId: selectedCachedModelId })}>新增</Button>
                  {previewModels.length ? <Button type="primary" onClick={importAllModels}>导入全部</Button> : null}
                </Flex>
                <Table
                  size="small"
                  rowKey="key"
                  pagination={false}
                  dataSource={configuredModels}
                  columns={modelColumns}
                  scroll={{ x: 760 }}
                  locale={{ emptyText: <Empty image={Empty.PRESENTED_IMAGE_SIMPLE} description="暂无模型配置" /> }}
                />
              </div>
            </div>
          </Form>
        </Drawer>
      ) : null}

      {modelEditor ? (
        <Modal
          open
          destroyOnHidden
          width={760}
          zIndex={1200}
          title={modelEditor.index === null ? '新增 模型配置' : '编辑 模型配置'}
          okText="确认"
          cancelText="取消"
          onCancel={() => setModelEditor(null)}
          onOk={() => void saveModelEditor()}
        >
          <Form form={modelForm} layout="vertical">
            <Flex gap={12} align="start">
              <Form.Item
                name="model_id"
                label="模型 ID"
                style={{ flex: 1 }}
                rules={[{ required: true, whitespace: true, message: '请输入模型 ID' }]}
              >
                <AutoComplete
                  options={previewModels.map((model) => ({ label: model.model_id, value: model.model_id }))}
                  placeholder="请输入模型 ID"
                />
              </Form.Item>
              <Form.Item
                name="context_window_input"
                label="上下文"
                style={{ width: 180 }}
                rules={[{
                  validator: (_, value) => {
                    try { parseContextWindow(value); return Promise.resolve(); }
                    catch (reason) { return Promise.reject(reason); }
                  }
                }]}
              >
                <AutoComplete options={[{ value: '32K' }, { value: '64K' }, { value: '128K' }, { value: '1M' }]} placeholder="例如 128K" />
              </Form.Item>
            </Flex>
            <Flex gap={24} align="center" style={{ marginBottom: 16 }}>
              <Space><Typography.Text>多模态</Typography.Text><Form.Item name="supports_multimodal" valuePropName="checked" noStyle><Switch /></Form.Item></Space>
              <Space><Typography.Text>启用</Typography.Text><Form.Item name="enabled" valuePropName="checked" noStyle><Switch /></Form.Item></Space>
            </Flex>
            <Typography.Title level={5}>模型计费规则</Typography.Title>
            <Flex gap={12}>
              <Form.Item name="pricing_provider_code" label="计费供应商" style={{ flex: 1 }}>
                <Select
                  options={pricingProviderOptions.length ? pricingProviderOptions : [{ label: 'zero', value: 'zero' }]}
                  onChange={() => modelForm.setFieldValue('pricing_model_id', undefined)}
                />
              </Form.Item>
              <Form.Item name="pricing_model_id" label="计费模型" style={{ flex: 1 }}>
                <Select options={pricingModelOptions.length ? pricingModelOptions : [{ label: 'any', value: 'any' }]} />
              </Form.Item>
            </Flex>
          </Form>
        </Modal>
      ) : null}

      {selected ? (
        <ProviderInstanceManager key={selected.provider_code}
          api={ctx.api} selected={selected} instances={selectedInstances}
          optionsResponse={optionsResponse} canManage={canManage} externalNotice={notice}
          onRefresh={refresh} onEdit={openEdit} onClose={() => setSelected(null)} />
      ) : null}
    </div>
  );
}

function ProviderInstanceManager({ api, selected, instances, optionsResponse, canManage, externalNotice, onRefresh, onEdit, onClose }) {
  const [mainInstance, setMainInstance] = useState(null);
  const [loading, setLoading] = useState(true);
  const [pending, setPending] = useState(null);
  const [notice, setNotice] = useState(null);
  const [editingGroup, setEditingGroup] = useState(null);
  const operationRef = useRef(false);
  const apiRef = useRef(api);
  apiRef.current = api;
  const mainPath = '/api/console/settings/model-providers/providers/{provider_code}/main-instance';
  const modelGroups = optionsResponse.providers?.find((provider) => provider.provider_code === selected.provider_code)?.model_groups || [];
  useEffect(() => {
    let active = true;
    setLoading(true);
    apiRef.current.get(mainPath, { path: { provider_code: selected.provider_code } }).then((value) => { if (active) setMainInstance(value); })
      .catch(() => { if (active) setNotice({ type: 'error', message: '主实例配置加载失败，请重试。' }); })
      .finally(() => { if (active) setLoading(false); });
    return () => { active = false; };
  }, [mainPath, selected.provider_code, instances]);

  async function refreshMain() {
    setMainInstance(await apiRef.current.get(mainPath, { path: { provider_code: selected.provider_code } }));
  }
  async function runOperation(key, action, message) {
    if (operationRef.current || !canManage) return false;
    operationRef.current = true;
    setPending(key);
    setNotice(null);
    let saved = false;
    try {
      await action();
      saved = true;
      const [refreshed] = await Promise.all([onRefresh(), refreshMain()]);
      if (!refreshed) throw new Error('refresh failed');
      setNotice({ type: 'success', message });
      return true;
    } catch (error) {
      setNotice({ type: saved ? 'warning' : 'error', message: saved
        ? '操作已完成，但数据刷新失败，请点击刷新重新加载。'
        : '操作失败，配置未确认保存。请刷新后重试；如有并发修改，请基于最新配置重新编辑。' });
      if (!saved) { try { await refreshMain(); } catch { setMainInstance(null); } }
      return saved;
    } finally {
      operationRef.current = false;
      setPending(null);
    }
  }
  async function saveMain(patch) {
    if (!mainInstance) return false;
    return runOperation('main', () => apiRef.current.put(mainPath, { path: { provider_code: selected.provider_code }, body: {
      auto_include_new_instances: mainInstance.auto_include_new_instances,
      model_routing_policies: mainInstance.model_routing_policies,
      expected_revision: mainInstance.revision,
      ...patch
    } }), '主实例配置已保存。');
  }
  async function savePolicy(policy) {
    if (!mainInstance) return false;
    const policies = mainInstance.model_routing_policies.filter((item) => item.model_id !== policy.model_id);
    const saved = await saveMain({ model_routing_policies: [...policies, policy] });
    if (saved) setEditingGroup(null);
    return saved;
  }
  async function reload() {
    setLoading(true);
    setNotice(null);
    try { const [refreshed] = await Promise.all([onRefresh(), refreshMain()]); if (!refreshed) throw new Error('refresh failed'); }
    catch { setNotice({ type: 'error', message: '加载失败，请重试。' }); }
    finally { setLoading(false); }
  }
  const disabled = !canManage || Boolean(pending) || loading;
  return <>
    <Modal open destroyOnHidden title={selected.display_name + ' · 实例'}
      width={960} styles={{ body: { maxHeight: 'calc(100dvh - 220px)', minHeight: 280, overflow: 'auto' } }}
      closable={!pending} maskClosable={!pending} onCancel={onClose}
      footer={<Space><Button loading={loading} disabled={Boolean(pending)} onClick={reload}>刷新</Button><Button disabled={Boolean(pending)} onClick={onClose}>关闭</Button></Space>}>
      {notice || externalNotice ? <Alert showIcon type={(notice || externalNotice).type} title={(notice || externalNotice).message} style={{ marginBottom: 12 }} /> : null}
      <Tabs defaultActiveKey="models" items={[
        { key: 'models', label: '模型管理', children: <>
          <Flex wrap gap={12} align="center" justify="space-between" style={{ marginBottom: 16 }}>
            <Space wrap><Typography.Text strong>主实例</Typography.Text><Tag color="blue">聚合视图</Tag>
              <Typography.Text>已纳入来源 {instances.filter((instance) => instance.included_in_main).length}</Typography.Text>
              <Typography.Text>聚合模型 {modelGroups.length}</Typography.Text></Space>
            <Space wrap><Typography.Text>新实例自动纳入主实例</Typography.Text>
              <Switch aria-label="新实例自动纳入主实例" checked={mainInstance?.auto_include_new_instances ?? false}
                disabled={disabled || !mainInstance} loading={pending === 'main'}
                onChange={(checked) => saveMain({ auto_include_new_instances: checked })} /></Space>
          </Flex>
          <Table size="small" rowKey="model_id" loading={loading} pagination={false} dataSource={modelGroups}
            scroll={{ x: 660 }} locale={{ emptyText: <Empty description="暂无聚合模型，请在来源管理中配置并纳入模型来源" /> }}
            columns={[
              { title: '模型 ID', dataIndex: 'model_id', width: 220 },
              { title: '来源分组', key: 'targets', render: (_, group) => <Space wrap>{group.targets.filter((target) => target.routing_enabled).map((target) => {
                const instance = instances.find((item) => item.id === target.source_instance_id);
                return canManage && instance ? <Button key={target.source_instance_id} type="link" size="small" disabled={disabled} onClick={() => onEdit(instance)}>{target.source_instance_display_name}</Button>
                  : <Tag key={target.source_instance_id}>{target.source_instance_display_name}</Tag>;
              })}</Space> },
              { title: '分发规则', key: 'rule', width: 180, render: (_, group) =>
                mainInstance?.distribution_rules?.find((rule) => rule.value === group.distribution_rule)?.display_name || group.distribution_rule },
              { title: '操作', key: 'actions', width: 90, render: (_, group) =>
                <Button type="link" disabled={disabled || !mainInstance} onClick={() => setEditingGroup(group)}>编辑</Button> }
            ]} />
        </> },
        { key: 'sources', label: '来源管理', children: instances.length ? <Collapse accordion defaultActiveKey={[instances[0].id]}
          items={instances.map((instance) => {
            const [label, color] = statusLabel(instance.status);
            return { key: instance.id, label: <Space wrap><Typography.Text strong>{instance.display_name}</Typography.Text><Tag color={color}>{label}</Tag>
              <Typography.Text type="secondary">生效模型 {instance.enabled_model_ids.length} · 缓存模型 {instance.model_count}</Typography.Text></Space>,
              children: <>
                <Space style={{ marginBottom: 12 }}><Typography.Text>纳入主实例</Typography.Text>
                  <Switch aria-label={instance.display_name + ' 纳入主实例'} checked={instance.included_in_main} disabled={disabled}
                    loading={pending === instance.id + ':include'} onChange={(checked) => runOperation(instance.id + ':include',
                      () => apiRef.current.patch(INSTANCES_PATH + '/{id}', { path: { id: instance.id }, body: {
                        display_name: instance.display_name, configured_models: instance.configured_models, config: {}, included_in_main: checked
                      } }), '来源纳入状态已保存。')} /></Space>
                <Descriptions size="small" column={1} items={[
                  { key: 'url', label: 'Base URL', children: <span style={{ overflowWrap: 'anywhere' }}>{String(instance.config_json.base_url || '未配置')}</span> },
                  { key: 'protocol', label: '协议', children: instance.protocol },
                  { key: 'models', label: '生效模型', children: <Space wrap>{instance.enabled_model_ids.length ? instance.enabled_model_ids.map((id) => <Tag key={id}>{id}</Tag>) : '未设置'}</Space> },
                  { key: 'refresh', label: '最近刷新', children: instance.catalog_refreshed_at || '尚未刷新' }
                ]} />
                {instance.catalog_last_error_message ? <Alert type="warning" showIcon title={instance.catalog_last_error_message} style={{ marginTop: 12 }} /> : null}
                {canManage ? <Space wrap style={{ marginTop: 12 }}>
                  <Button disabled={disabled} onClick={() => onEdit(instance)}>编辑</Button>
                  <Button disabled={disabled} loading={pending === instance.id + ':detect'} onClick={() => runOperation(instance.id + ':detect',
                    async () => { const result = await apiRef.current.post(INSTANCES_PATH + '/{id}/validate', { path: { id: instance.id } });
                      if (result.instance.status === 'invalid') throw new Error('invalid'); }, '来源探测已完成。')}>探测</Button>
                  <Button disabled={disabled} loading={pending === instance.id + ':refresh'} onClick={() => runOperation(instance.id + ':refresh',
                    async () => { const result = await apiRef.current.post(INSTANCES_PATH + '/{id}/models/refresh', { path: { id: instance.id } });
                      if (result.refresh_status === 'failed') throw new Error('refresh failed'); }, '模型缓存已刷新。')}>刷新模型</Button>
                  <Popconfirm title={'删除来源 ' + instance.display_name + '？'} description="删除后该来源将不再参与模型分发。" okText="删除" cancelText="取消"
                    disabled={disabled} onConfirm={() => runOperation(instance.id + ':delete', () => apiRef.current.delete(INSTANCES_PATH + '/{id}', { path: { id: instance.id } }), '模型来源已删除。')}>
                    <Button danger disabled={disabled}>删除</Button>
                  </Popconfirm>
                </Space> : null}
              </> };
          })} /> : <Empty description="该供应商尚未接入实例" /> }
      ]} />
    </Modal>
    {editingGroup ? <RoutingPolicyEditor group={editingGroup}
      policy={mainInstance?.model_routing_policies.find((policy) => policy.model_id === editingGroup.model_id)}
      definitions={mainInstance?.distribution_rules || []} saving={Boolean(pending)}
      onSave={savePolicy} onClose={() => setEditingGroup(null)} /> : null}
  </>;
}

function RoutingPolicyEditor({ group, policy, definitions, saving, onSave, onClose }) {
  const [rule, setRule] = useState(policy?.distribution_rule || group.distribution_rule);
  const [saveError, setSaveError] = useState(null);
  const [order, setOrder] = useState(() => {
    const available = new Set(group.targets.map((target) => target.source_instance_id));
    const existing = (policy?.provider_instance_ids || []).filter((id) => available.has(id));
    return [...existing, ...group.targets.map((target) => target.source_instance_id).filter((id) => !existing.includes(id))];
  });
  const [excluded, setExcluded] = useState(policy?.excluded_provider_instance_ids || group.targets.filter((target) => !target.routing_enabled).map((target) => target.source_instance_id));
  function move(index, delta) {
    setOrder((current) => { const next = [...current]; [next[index], next[index + delta]] = [next[index + delta], next[index]]; return next; });
  }
  return <Modal open title="编辑分发规则" width={640} zIndex={1200}
    closable={!saving} maskClosable={!saving} onCancel={onClose} okText="保存" cancelText="取消"
    confirmLoading={saving} cancelButtonProps={{ disabled: saving }} okButtonProps={{ disabled: saving || !definitions.some((item) => item.value === rule) }}
    onOk={async () => { setSaveError(null); const saved = await onSave({
      model_id: group.model_id, distribution_rule: rule,
      distribution_rule_contract_version: definitions.find((item) => item.value === rule)?.contract_version,
      distribution_rule_config: policy?.distribution_rule === rule ? policy.distribution_rule_config : {},
      provider_instance_ids: order, excluded_provider_instance_ids: order.filter((id) => excluded.includes(id))
    }); if (!saved) setSaveError('保存失败，请关闭后重新打开以读取最新配置，再重试。'); }}>
    <Space orientation="vertical" style={{ width: '100%' }} size={16}>
      {saveError ? <Alert type="error" showIcon title={saveError} /> : null}
      <Typography.Text strong>{group.model_id}</Typography.Text>
      <Select aria-label="分发规则" style={{ width: '100%' }} value={rule} disabled={saving}
        options={definitions.map((item) => ({ value: item.value, label: item.display_name }))} onChange={setRule} />
      <Typography.Text type="secondary">调整来源顺序，并选择参与该模型分发的来源。</Typography.Text>
      <Table size="small" rowKey="source_instance_id" pagination={false} dataSource={order.map((id) => group.targets.find((target) => target.source_instance_id === id))}
        columns={[
          { title: '来源', dataIndex: 'source_instance_display_name' },
          { title: '顺序', key: 'order', render: (_, target, index) => <Space>
            <Button size="small" aria-label={target.source_instance_display_name + ' 上移'} disabled={saving || index === 0} onClick={() => move(index, -1)}>上移</Button>
            <Button size="small" aria-label={target.source_instance_display_name + ' 下移'} disabled={saving || index === order.length - 1} onClick={() => move(index, 1)}>下移</Button>
          </Space> },
          { title: '参与分发', key: 'enabled', render: (_, target) => <Switch aria-label={target.source_instance_display_name + ' 参与分发'}
            checked={!excluded.includes(target.source_instance_id)} disabled={saving}
            onChange={(checked) => setExcluded((current) => checked ? current.filter((id) => id !== target.source_instance_id) : [...current, target.source_instance_id])} /> }
        ]} />
    </Space>
  </Modal>;
}

import React, { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { Alert, Button, Empty, Input, Modal, Space, Spin, Tag, Tooltip, Typography } from 'antd';

const OFFICIAL_PATH = '/api/console/settings/model-providers/plugins/official-catalog';
const FAMILY_PATH = '/api/console/settings/model-providers/plugins/families';
const INSTALL_PATH = '/api/console/settings/model-providers/plugins/install-official';
const UPGRADE_PATH = '/api/console/settings/model-providers/plugins/families/{provider_code}/upgrade-latest';
const TASK_PATH = '/api/console/settings/model-providers/plugins/tasks/{task_id}';
const PROVIDER_CHANGED_EVENT = 'frontstage:model-provider-catalog-changed';
const RELEASES_URL = 'https://github.com/taichuy/1flowbase-official-plugins/releases';

function compareVersion(left, right) {
  return String(left || '').localeCompare(String(right || ''), undefined, { numeric: true, sensitivity: 'base' });
}

function tagColor(tag) {
  if (tag === 'latest') return 'gold';
  if (tag === 'installed' || tag === 'active') return 'blue';
  if (tag === 'hybrid') return 'purple';
  if (tag === 'dynamic') return 'cyan';
  if (tag === 'failed') return 'red';
  if (tag === 'below_minimum_host_version') return 'orange';
  return 'default';
}

function isTerminal(status) {
  return ['success', 'succeeded', 'failed', 'canceled', 'timed_out'].includes(status);
}

function isSucceeded(status) {
  return status === 'success' || status === 'succeeded';
}

export default function OfficialPluginBlock({ ctx }) {
  const [catalog, setCatalog] = useState({ entries: [], page: {}, registry_url: RELEASES_URL });
  const [families, setFamilies] = useState([]);
  const [query, setQuery] = useState('');
  const [busy, setBusy] = useState(false);
  const [activePluginId, setActivePluginId] = useState(null);
  const [notice, setNotice] = useState(null);
  const [pending, setPending] = useState(null);
  const apiRef = useRef(ctx.api);
  const localeRef = useRef(ctx.ui.locale || 'zh_Hans');
  apiRef.current = ctx.api;
  localeRef.current = ctx.ui.locale || 'zh_Hans';

  const refresh = useCallback(async () => {
    setBusy(true);
    try {
      const [official, familyResponse] = await Promise.all([
        apiRef.current.get(OFFICIAL_PATH, {
          query: {
            plugin_type: 'model_provider',
            locale: localeRef.current,
            limit: 20
          }
        }),
        apiRef.current.get(FAMILY_PATH, {
          query: {
            plugin_type: 'model_provider',
            locale: localeRef.current
          }
        })
      ]);
      setCatalog(official || { entries: [], page: {}, registry_url: RELEASES_URL });
      setFamilies(Array.isArray(familyResponse?.entries) ? familyResponse.entries : []);
    } catch (reason) {
      setNotice({ type: 'error', message: '官方插件目录暂时无法访问，请重试。' });
    } finally {
      setBusy(false);
    }
  }, []);

  useEffect(() => {
    refresh();
  }, [refresh]);

  const entries = useMemo(() => {
    const preferred = new Map();
    for (const entry of Array.isArray(catalog?.entries) ? catalog.entries : []) {
      const current = preferred.get(entry.provider_code);
      if (!current || compareVersion(entry.latest_version, current.latest_version) > 0) {
        preferred.set(entry.provider_code, entry);
      }
    }
    const needle = query.trim().toLowerCase();
    return Array.from(preferred.values()).filter((entry) =>
      !needle ||
      String(entry.display_name || '').toLowerCase().includes(needle) ||
      String(entry.provider_code || '').toLowerCase().includes(needle)
    );
  }, [catalog, query]);

  async function waitForTask(taskId) {
    for (let attempt = 0; attempt < 60; attempt += 1) {
      const task = await apiRef.current.get(TASK_PATH, { path: { task_id: taskId } });
      if (task?.finished_at || isTerminal(task?.status)) return task;
      await new Promise((resolve) => window.setTimeout(resolve, 1000));
    }
    throw new Error('安装任务仍在执行，请稍后刷新查看。');
  }

  async function perform(entry, family, compatibilityOverride) {
    setActivePluginId(entry.plugin_id);
    setNotice({ type: 'info', message: family?.has_update ? '正在升级插件…' : '正在下载并安装插件…' });
    try {
      let response;
      if (family?.has_update) {
        response = await ctx.api.post(UPGRADE_PATH, {
          path: { provider_code: entry.provider_code },
          body: compatibilityOverride ? { compatibility_override: compatibilityOverride } : {}
        });
      } else {
        response = await ctx.api.post(INSTALL_PATH, {
          body: {
            plugin_id: entry.plugin_id,
            ...(compatibilityOverride ? { compatibility_override: compatibilityOverride } : {})
          }
        });
      }
      const task = response?.task || response;
      const finalTask = task?.id ? await waitForTask(task.id) : task;
      if (finalTask?.status && !isSucceeded(finalTask.status)) {
        throw new Error(finalTask.status_message || '插件任务执行失败。');
      }
      setNotice({ type: 'success', message: family?.has_update ? '插件已升级到最新版本。' : '插件已安装到当前 workspace。' });
      await refresh();
      window.dispatchEvent(new CustomEvent(PROVIDER_CHANGED_EVENT));
    } catch (reason) {
      setNotice({
        type: 'error',
        message: reason instanceof Error ? reason.message : '插件安装失败，请稍后重试。'
      });
    } finally {
      setActivePluginId(null);
    }
  }

  function requestInstall(entry, family) {
    const belowMinimum = entry.compatibility_status === 'below_minimum_host_version';
    const compatibilityOverride = belowMinimum
      ? {
          reason: 'below_minimum_host_version',
          acknowledged_current_host_version: entry.current_host_version,
          acknowledged_minimum_host_version: entry.minimum_host_version
        }
      : undefined;
    setPending({ entry, family, belowMinimum, compatibilityOverride });
  }

  function openExternal(url) {
    if (url) window.open(url, '_blank', 'noopener,noreferrer');
  }

  return (
    <div style={{ minHeight: 720, padding: '18px 18px 24px', background: 'rgba(255,255,255,0.84)', borderRadius: 16 }}>
      <Space wrap size={8} style={{ width: '100%', justifyContent: 'space-between', marginBottom: 14 }}>
        <Typography.Title level={4} style={{ margin: 0 }}>下载插件</Typography.Title>
        <Space size={8}>
          <Button size="small" onClick={() => openExternal(catalog?.registry_url || RELEASES_URL)}>来源</Button>
          <Button size="small" onClick={() => openExternal(RELEASES_URL)}>前往仓库下载</Button>
        </Space>
      </Space>

      <Input.Search
        allowClear
        placeholder="搜索可安装供应商"
        value={query}
        onChange={(event) => setQuery(event.target.value)}
        style={{ marginBottom: 14 }}
      />

      {notice ? (
        <Alert
          showIcon
          closable={notice.type !== 'info'}
          type={notice.type}
          message={notice.message}
          onClose={() => setNotice(null)}
          style={{ marginBottom: 12 }}
        />
      ) : null}

      <style>{`
        .official-plugin-catalog-scroll {
          scrollbar-width: none;
          -ms-overflow-style: none;
        }
        .official-plugin-catalog-scroll::-webkit-scrollbar {
          display: none;
        }
      `}</style>

      <Spin spinning={busy}>
        <div
          className="official-plugin-catalog-scroll"
          style={{ display: 'grid', gap: 2, maxHeight: 620, overflowY: 'auto', paddingRight: 2 }}
        >
          {entries.length === 0 && !busy ? <Empty description="暂无可下载的模型插件" /> : null}
          {entries.map((entry) => {
            const family = families.find((item) => item.provider_code === entry.provider_code);
            const installed = Boolean(family) || ['assigned', 'installed'].includes(entry.install_status);
            const upgrading = Boolean(family?.has_update);
            const running = activePluginId === entry.plugin_id;
            const tags = [
              family?.current_version || entry.latest_version,
              upgrading ? entry.latest_version : installed ? 'latest' : entry.install_status,
              entry.model_discovery_mode
            ].filter(Boolean);
            const buttonText = running
              ? upgrading ? '升级中…' : '安装中…'
              : upgrading
                ? '升级至最新版'
                : installed
                  ? '当前已是最新版'
                  : '安装到当前 workspace';

            return (
              <div key={entry.provider_code} style={{ padding: '16px 2px 18px', borderBottom: '1px solid rgba(5,5,5,0.08)' }}>
                <Space align="start" size={12} style={{ width: '100%' }}>
                  <img
                    src={entry.icon || '/icon.svg'}
                    alt=""
                    width={28}
                    height={28}
                    style={{ flex: '0 0 auto', borderRadius: 7, objectFit: 'contain', background: '#f5f5f5' }}
                  />
                  <div style={{ minWidth: 0, flex: 1 }}>
                    <Typography.Text strong style={{ display: 'block', fontSize: 16, marginBottom: 7 }}>
                      {entry.display_name || entry.provider_code}
                    </Typography.Text>
                    <Space wrap size={[5, 5]}>
                      {tags.map((tag, index) => (
                        <Tag key={String(tag) + index} color={tagColor(tag)} style={{ marginInlineEnd: 0 }}>
                          {tag}
                        </Tag>
                      ))}
                      {entry.compatibility_status === 'below_minimum_host_version' ? (
                        <Tooltip title="当前主机版本低于插件声明的最低版本">
                          <Tag color="orange">兼容性风险</Tag>
                        </Tooltip>
                      ) : null}
                    </Space>
                    {entry.description ? (
                      <Typography.Paragraph type="secondary" ellipsis={{ rows: 2 }} style={{ margin: '9px 0 0' }}>
                        {entry.description}
                      </Typography.Paragraph>
                    ) : null}
                  </div>
                </Space>
                <Space wrap size={8} style={{ width: '100%', justifyContent: 'flex-end', marginTop: 12 }}>
                  {entry.help_url ? <Button size="small" onClick={() => openExternal(entry.help_url)}>文档</Button> : null}
                  <Button
                    size="small"
                    type={installed && !upgrading ? 'default' : 'primary'}
                    loading={running}
                    disabled={running || (installed && !upgrading)}
                    onClick={() => requestInstall(entry, family)}
                  >
                    {buttonText}
                  </Button>
                </Space>
              </div>
            );
          })}
        </div>
      </Spin>

      <Modal
        centered
        open={Boolean(pending)}
        title={pending?.family?.has_update ? '升级模型插件' : '安装模型插件'}
        okText={pending?.belowMinimum ? '已了解，仍要继续' : '确认'}
        cancelText="取消"
        confirmLoading={Boolean(pending && activePluginId === pending.entry.plugin_id)}
        onCancel={() => setPending(null)}
        onOk={() => {
          const current = pending;
          setPending(null);
          if (current) {
            return perform(current.entry, current.family, current.compatibilityOverride);
          }
        }}
      >
        {pending?.belowMinimum
          ? '当前主机版本低于插件声明的最低版本，继续操作可能无法正常运行。'
          : pending
            ? '将把 ' + pending.entry.display_name + ' ' + pending.entry.latest_version + ' 安装到当前 workspace。'
            : null}
      </Modal>
    </div>
  );
}
